head.script:
scwin.createPopupLayer = function () {
    if (document.getElementById('customAlertPopup')) return;

    var popupHtml = `
        <div id="customAlertPopup" style="position: fixed; top: 0; left: 0; width: 100%; height: 100%; background: rgba(0,0,0,0.5); z-index: 9999; display: none; align-items: center; justify-content: center; font-family: 'Pretendard', sans-serif;">
            <div style="background: white; padding: 24px; border-radius: 8px; box-shadow: 0 5px 15px rgba(0,0,0,0.3); min-width: 320px; max-width: 450px; text-align: center; box-sizing: border-box;">
                <div id="popupMessage" style="margin-bottom: 24px; font-size: 16px; line-height: 1.6; color: #333; white-space: pre-wrap; word-break: break-word;"></div>
                <div>
                    <button id="popupConfirm" style="background: #007bff; color: white; border: none; padding: 10px 20px; margin: 0 5px; border-radius: 5px; cursor: pointer; font-size: 14px; font-weight: 500;">확인</button>
                    <button id="popupCancel" style="background: #6c757d; color: white; border: none; padding: 10px 20px; margin: 0 5px; border-radius: 5px; cursor: pointer; font-size: 14px; font-weight: 500;">취소</button>
                </div>
            </div>
        </div>
    `;
    document.body.insertAdjacentHTML('beforeend', popupHtml);
};

scwin.showPopup = function (message, isConfirm, callback) {
    var popup = document.getElementById('customAlertPopup');
    if (!popup) {
        scwin.createPopupLayer();
        popup = document.getElementById('customAlertPopup');
    }

    var messageEl = document.getElementById('popupMessage');
    var confirmBtn = document.getElementById('popupConfirm');
    var cancelBtn = document.getElementById('popupCancel');

    messageEl.innerHTML = message.replace(/\\n/g, '<br>');

    if (isConfirm) {
        cancelBtn.style.display = 'inline-block';
        confirmBtn.onclick = function () {
            popup.style.display = 'none';
            if (callback) callback(true);
        };
        cancelBtn.onclick = function () {
            popup.style.display = 'none';
            if (callback) callback(false);
        };
    } else {
        cancelBtn.style.display = 'none';
        confirmBtn.onclick = function () {
            popup.style.display = 'none';
            if (callback) callback();
        };
    }

    popup.style.display = 'flex';
};

// JWT 토큰 파싱 함수
scwin.parseJwt = function (token) {
    try {
        const base64Url = token.split('.')[1];
        const base64 = base64Url.replace(/-/g, '+').replace(/_/g, '/');
        const jsonPayload = decodeURIComponent(atob(base64).split('').map(function (c) {
            return '%' + ('00' + c.charCodeAt(0).toString(16)).slice(-2);
        }).join(''));
        return JSON.parse(jsonPayload);
    } catch (e) {
        console.error("JWT 파싱 오류:", e);
        return null;
    }
};

// 페이지 로드 시 초기화
scwin.onpageload = function () {
    var mode = $p.getParameter("mode");
    console.log("mode", mode);
    if (mode !== "preview") {
        const subDomain = scwin.getQueryParam('tenant');

        const dm = dma_login;
        const dm_sub = dm_subdomain;

        if (dm && typeof dm.set === 'function') {
            dm.set('subDomain', subDomain !== null ? subDomain : "basic");
            dm_sub.set('subDomain', subDomain !== null ? subDomain : "basic");
            dm_sub.set('mode', "login");
        };
        scwin.createPopupLayer();

        $c.sbm.execute(loadCustom);
    }
};

// 미리보기 모드용 함수
scwin.applyCustomization = function (data) {
    scwin.loadCustomization(data);
};

// 커스터마이징 적용 함수
scwin.overlayElement = null;

scwin.containKorean = function(text){
  return /^[ㄱ-ㅎㅏ-ㅣ가-힣]/.test(text);
}

scwin.loadCustomization = function (c) {
   if (!c) return;

    // 테넌트 이름을 전역 변수에 저장
    if (c.tenantName) {
        scwin.lastLoadedTenantName = c.tenantName;
        console.log("loadCustomization에서 테넌트 이름 저장:", c.tenantName);
    }

    if(scwin.containKorean(c.tenantName)){
        loginGuideTxt.setValue(c.tenantName+"에 로그인하세요")
    }else{
        loginGuideTxt.setValue("SIGN IN TO "+  c.tenantName.toUpperCase());
    }

    // 나머지 커스터마이징 로직은 그대로...
    if (leftPreview && c.backgroundImage) {
        leftPreview.setStyle("backgroundImage", "url(" + c.backgroundImage + ")");
    }

    if (logoImage && c.logo) {
        logoImage.setSrc(c.logo);
        const logoElement = document.getElementById(logoImage.getID());
        if (logoElement && c.logoSize) {
            var size = String(c.logoSize).endsWith('px') ? c.logoSize : c.logoSize + 'px';
            logoElement.style.setProperty('width', size, 'important');
            logoElement.style.setProperty('height', size, 'important');
        }
    }

    if (btn_login && c.primaryColor) {
        btn_login.setStyle("backgroundColor", c.primaryColor);
        btn_login.setStyle("color", c.accentColor);
    }

    const setLabelStyle = function (id, text, color, size, weight) {
        if (!id) return;

        if (text) id.setLabel(text);
        if (color) id.setStyle("color", color);
        if (weight) id.setStyle("fontWeight", weight);

        var element = document.getElementById(id.getID());
        if (element && size) {
            var fontSize = String(size).endsWith('px') ? size : size + 'px';
            element.style.setProperty('font-size', fontSize, 'important');
        }
    };

    setLabelStyle(mainTitle, c.mainTitle, c.mainTitleColor, c.mainTitleSize, c.mainTitleFont);
    setLabelStyle(subTitle, c.subTitle, c.subTitleColor, c.subTitleSize, c.subTitleFont);
    setLabelStyle(extraTitle, c.extraTitle, c.extraTitleColor, c.extraTitleSize, c.extraTitleFont);

    // 오버레이 배경 처리...
    if (!scwin.overlayElement) {
        scwin.overlayElement = document.createElement("div");
        scwin.overlayElement.style.position = "absolute";
        scwin.overlayElement.style.top = 0;
        scwin.overlayElement.style.left = 0;
        scwin.overlayElement.style.right = 0;
        scwin.overlayElement.style.bottom = 0;
        scwin.overlayElement.style.zIndex = 1;

        if (leftPreview) {
            leftPreview.appendChild(scwin.overlayElement);
        }
    }

    if (c.overlayColor) scwin.overlayElement.style.backgroundColor = c.overlayColor;
    if (c.overlayOpacity) scwin.overlayElement.style.opacity = (parseInt(c.overlayOpacity) || 0) / 100;
};

// 저장된 아이디 로드
scwin.loadSavedUserId = function () {
    try {
        var savedUserId = localStorage.getItem("savedUserId");
        if (savedUserId) {
            // 데이터 바인딩을 통해 값 설정
            $p.setValueByID("data:loginInfo.userId", savedUserId);
            $p.setValueByID("data:loginInfo.rememberMe", "Y");
        }
    } catch (e) {
        console.warn("로컬 스토리지 접근 실패:", e);
    }
};

// 엔터키 이벤트 바인딩
scwin.bindEnterKeyEvents = function () {
    // 아이디 입력 필드에서 엔터키
    inp_userId.bind("keypress", function (e) {
        if (e.keyCode === 13) {
            e.preventDefault();
            inp_password.focus();
        }
    });

    // 비밀번호 입력 필드에서 엔터키
    inp_password.bind("keypress", function (e) {
        if (e.keyCode === 13) {
            e.preventDefault();
            scwin.login();
        }
    });
};



// 입력값 검증
scwin.validateLogin = function (userId, password) {
    if (!userId || userId.trim() === "") {
        $p.alert("아이디를 입력해주세요.", function () {
            inp_userId.focus();
        });
        return false;
    }

    if (!password || password.trim() === "") {
        $p.alert("비밀번호를 입력해주세요.", function () {
            inp_password.focus();
        });
        return false;
    }
    if (userId.length < 3) {
        $p.alert("아이디는 3글자 이상 입력해주세요.", function () {
            inp_userId.focus();
        });
        return false;
    }

    return true;
};

scwin.getQueryParam = function (name) {
    const params = new URLSearchParams(window.location.search);
    return params.get(name);
};


// 로그인 성공 처리
scwin.onLoginSuccess = function () {
    scwin.setLoginButtonState(false);

    var userId = $p.getValueByID("data:loginInfo.userId");
    var rememberMe = $p.getValueByID("data:loginInfo.rememberMe");

    try {
        // 아이디 저장 처리
        if (rememberMe === "Y") {
            localStorage.setItem("savedUserId", userId);
        } else {
            localStorage.removeItem("savedUserId");
        }

        // 사용자 정보 저장
        sessionStorage.setItem("loggedInUser", userId);

    } catch (e) {
        console.warn("스토리지 저장 실패:", e);
    }

    $p.alert("로그인되었습니다.", function () {
        scwin.redirectToMainPage();
    });
};

// 로그인 실패 처리
scwin.onLoginFailure = function () {
    scwin.setLoginButtonState(false);

    $p.alert("아이디 또는 비밀번호가 올바르지 않습니다.", function () {
        $p.setValueByID("data:loginInfo.password", "");
        inp_password.focus();
    });
};

// 로그인 버튼 상태 변경
scwin.setLoginButtonState = function (isLoading) {
    // var btn_login = $p.getComponentById("btn_login");
    if (isLoading) {
        btn_login.setDisabled(true);
        btn_login.setText("로그인 중...");
    } else {
        btn_login.setDisabled(false);
        btn_login.setText("Login");
    }
};

// 메인 페이지로 리다이렉트
scwin.redirectToMainPage = function () {
    try {
        if (parent && parent.scwin && parent.scwin.goToMain) {
            parent.scwin.goToMain();
        } else {
            console.log("메인 페이지로 이동합니다.");
            // window.location.href = "/main.xml";
        }
    } catch (e) {
        console.log("메인 페이지 이동 처리");
    }
};


// 실제 서버 통신 완료 후 콜백
scwin.loginSubmitHandler = function (e) {
    if (e.retCode === "0" || e.responseStatusCode === 200) {
        scwin.onLoginSuccess();
    } else {
        scwin.onLoginFailure();
    }
};

scwin.loadCustom_submitdone = function (e) {
    var elData = e.responseJSON;
    console.log("받아온데이터입니다", elData);
    if (elData?.code === "E001") {
        location.href = "/InsWebApp/websquare/websquare.html?w2xPath=/InsWebApp/error/404tenant.xml";
    }else if (Object.keys(elData).length === 1) {
        elData = scwin.defaultData(elData.tenantName);
    }
    scwin.loadCustomization(elData);
};

// 로그인 함수
scwin.login = function (e) {
    $c.sbm.execute(login);
};

// 로그인 응답 처리
scwin.login_submitdone = function (e) {
    console.log("응답 전체:", e);
    var responseData = e.responseJSON;
    var elHeader = e.responseJSON.elHeader;

    if (elHeader && elHeader.resSuc === true) {
        console.log("Response Headers:", e.responseHeadersJSON);
        var headers = {};
        try {
            headers = JSON.parse(e.responseHeadersJSON);
        } catch (err) {
            console.error("헤더 JSON 파싱 오류:", err);
        }

        var accessToken = headers.authorization;
        var refreshToken = headers["refresh-token"];
        console.log("Access Token:", accessToken);
        console.log("Refresh Token:", refreshToken);

        if (accessToken) {
            sessionStorage.setItem('accessToken', accessToken);
        }
        if (refreshToken) {
            sessionStorage.setItem('refreshToken', refreshToken);
        }

        var tenantId = null;
        if (accessToken) {
            const tokenString = accessToken.startsWith('Bearer ') ? accessToken.substring(7) : accessToken;
            const tokenPayload = scwin.parseJwt(tokenString);

            if (tokenPayload && tokenPayload.tenantId) {
                tenantId = tokenPayload.tenantId;
            }
        }

        console.log("추출된 테넌트 ID:", tenantId);

        // 현재 테넌트 이름 추출 - 여러 방법으로 시도
        var currentTenantName = null;

        // 방법 1: URL 파라미터에서 추출
        const urlTenant = scwin.getQueryParam('tenant');
        if (urlTenant) {
            currentTenantName = urlTenant;
            console.log("URL에서 테넌트 이름 추출:", currentTenantName);
        }

        // 방법 2: 전역 변수에서 확인
        if (!currentTenantName && window.currentTenantName) {
            currentTenantName = window.currentTenantName;
            console.log("전역변수에서 테넌트 이름 추출:", currentTenantName);
        }

        // 방법 3: loadCustomization에서 사용된 tenantName 확인
        if (!currentTenantName && scwin.lastLoadedTenantName) {
            currentTenantName = scwin.lastLoadedTenantName;
            console.log("마지막 로드된 테넌트 이름 사용:", currentTenantName);
        }

        console.log("최종 현재 테넌트 이름:", currentTenantName);

        // 테넌트 이름을 sessionStorage에 저장 (강화된 저장)
        if (currentTenantName) {
            sessionStorage.setItem('currentTenantName', currentTenantName);
            console.log("SessionStorage에 테넌트 이름 저장 완료:", currentTenantName);

            // 확인
            const saved = sessionStorage.getItem('currentTenantName');
            console.log("저장 확인:", saved);
        } else {
            console.warn("저장할 테넌트 이름이 없습니다!");
        }

        if (tenantId) {
            var dashboardUrl = "/InsWebApp/websquare/websquare.html?w2xPath=/InsWebApp/main/tenant_user_dashboard.xml&tenant=" + encodeURIComponent(tenantId);
            console.log("대시보드 이동 URL:", dashboardUrl);
            location.href = dashboardUrl;
        } else {
            scwin.showPopup("로그인은 성공했으나, 토큰에서 테넌트 정보를 찾을 수 없습니다. 관리자에게 문의하세요.");
        }

    } else {
        scwin.showPopup(elHeader ? elHeader.resMsg : "로그인 응답이 유효하지 않습니다.");
    }
};

// 카카오 로그인 함수들
scwin.btn_kakao_onclick = function (e) {
   // 3.1 URL 파라미터에서 tenant 추출
    var tenant = $p.getParameter("tenant");
    console.log(tenant);
    // 3.2 서비스 코드 정의
    var service = "TNU0000KC";
    // 3.3 동적으로 action URL 생성 (중괄호 없이)
    var url = "/InsWebApp/TNU0000KL.pwkjson?service=" 
              + service 
              + "&tenant=" + encodeURIComponent(tenant);
    // 3.4 submission에 action 설정
    console.log(url);

    var subObj = $p.getSubmission("kakao_login");
    console.log(subObj);

  subObj.action = url;

  $p.executeSubmission("kakao_login");

};

scwin.kakao_login_submitdone = function (e) {
    if (e.responseStatusCode == 200 && e.responseJSON.success === true && e.responseJSON.loginUrl) {
        location.href = e.responseJSON.loginUrl;
    } else {
        scwin.showPopup(e.responseJSON.message || "카카오 로그인 URL 호출 실패");
    }
};

scwin.togglePassword_onclick = function (e) {
    const passwordField = document.getElementById('mf_inp_password');
    if (inp_password.hasClass("show")) {
        passwordField.type = "text";
        inp_password.toggleClass("show")
        togglePassword.setSrc("/InsWebApp/images/icons/open-eye.svg")
    } else {
        passwordField.type = "password";
        inp_password.toggleClass("show")
        togglePassword.setSrc('/InsWebApp/images/icons/close-eye.svg')
    }
};

scwin.defaultData = function (name) {
    const data = {
        backgroundImage: 'https://images.unsplash.com/photo-1497366216548-37526070297c?w=800&h=600&fit=crop', // 깔끔한 오피스 이미지
        logo: '',
        logoSize: 60,
        mainTitle: '비즈니스의 새로운 시작을 환영합니다.',
        mainTitleSize: 36,
        mainTitleColor: '#ffffff',
        mainTitleFont: 'font-semibold',
        subTitle: '안전하고 효율적인 비즈니스 솔루션',
        subTitleSize: 18,
        subTitleColor: '#e5e7eb',
        subTitleFont: 'font-normal',
        extraTitle: '안전하고 신뢰할 수 있는 플랫폼으로 더 나은 비즈니스를 위한 첫걸음을 시작하세요',
        extraTitleSize: 16,
        extraTitleColor: '#d1d5db',
        extraTitleFont: 'font-light',
        overlayOpacity: 35,
        overlayColor: '#1f2937',
        primaryColor: '#3b82f6',
        accentColor: '#6366f1',
        tenantName: name,
    }
    // 부모의 데이터맵에도 세팅? -> 부모가 있는경우 
    // 현재 loginCustom시 datamap에 데이터 매핑이 안되어있어서 하나만 바꿔도 제대로 인식 못하는 문제 있음 -> 해결 필요
    return data;
}
